    /// <summary>
    /// Performs specific actions when a field is modified.
    /// </summary>
    /// <param name="_fieldId">
    /// The field ID of the field that has been modified.
    /// </param>
    /// <param name="_userInput">
    /// A Boolean value indicating whether the field change is initiated through direct user input; optional.
    /// </param>
    /// <remarks>
    /// This is overridden to allow for specific actions when a field is modified.
    /// </remarks>
    public void modifiedField(FieldId _fieldId, boolean _userInput)
    {
        InventDim inventDim;
        InventItemPurchSetup    inventItemPurchSetup;

        next  modifiedField(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(PurchLine, ItemId):
                
                inventItemPurchSetup = InventItemPurchSetup::find(this.Itemid,this.InventdimId);
                
                if (inventItemPurchSetup.METPurchUnit)
                {
                    this.PurchUnit = inventItemPurchSetup.METPurchUnit;
                }

                break;

           
        }
    }

/// <summary>
/// Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2
/// </summary>
/// <returns>Change reason code description</returns>
[SysClientCacheDataMethodAttribute(true)]
display Description METDisplayChangeReasoncodeDesc()
{
    return METPOChangeReasonCodeSetup::find(this.METPOLineChangeReasonCode).ChangeReasonDesc;
}
